<script setup lang="ts">import{computed}from 'vue';import type{Energy}from '../types/domain';import{fmt}from '../utils/format';const props=defineProps<{energy:Energy}>();const upper=computed(()=>Math.max(1e-8,props.energy.statistic,...props.energy.null_statistics)*1.08);const bins=computed(()=>{const b=Array(24).fill(0)as number[];for(const x of props.energy.null_statistics)b[Math.min(23,Math.floor(x/upper.value*24))]++;return b});const max=computed(()=>Math.max(1,...bins.value));</script><template><section class="energy-plot"><div class="plot-title"><h2>差异，放回交换性前提里读。</h2><span>标签置换零分布</span></div><svg viewBox="0 0 640 230" role="img" aria-label="energy统计量的置换零分布与观测值"><line x1="35" x2="615" y1="185" y2="185" class="ring"/><rect v-for="(b,i) in bins" :x="35+i*24" :y="185-b/max*140" width="21" :height="b/max*140" class="null-bar"/><line :x1="35+energy.statistic/upper*576" :x2="35+energy.statistic/upper*576" y1="20" y2="188" class="observed-line"/><text x="35" y="209" class="axis-label">0</text><text x="611" y="209" text-anchor="end" class="axis-label">{{fmt(upper,4)}}</text></svg><p class="plot-note">朱线为观测E={{fmt(energy.statistic,4)}}；置换{{energy.permutations}}次，达到或超过观测{{energy.extreme}}次，p=({{energy.extreme}}+1)/({{energy.permutations}}+1)={{fmt(energy.p_value,4)}}。</p></section></template>
